class CanaryController:
    STAGES = [0.05, 0.25, 0.50, 1.00]
    MIN_SAMPLES_PER_STAGE = 500
    MAX_RELATIVE_DEGRADATION = 0.15  # candidate error rate vs baseline

    def __init__(self, metrics_store):
        self.stage_index = 0
        self.metrics = metrics_store  # rolling window counters per arm

    def traffic_split(self) -> float:
        """Fraction of traffic routed to the candidate model right now."""
        return self.STAGES[self.stage_index]

    def route(self, request_id: str) -> str:
        split = self.traffic_split()
        return "candidate" if stable_hash(request_id) < split else "baseline"

    def record_result(self, arm: str, success: bool):
        self.metrics.record(arm, success)

    def evaluate_and_advance(self):
        baseline = self.metrics.window("baseline")
        candidate = self.metrics.window("candidate")

        if candidate.sample_size < self.MIN_SAMPLES_PER_STAGE:
            return  # not enough data yet, hold current stage

        if self._is_regression(baseline, candidate):
            self.rollback()
            return

        if self.stage_index < len(self.STAGES) - 1:
            self.stage_index += 1  # advance to next traffic percentage

    def _is_regression(self, baseline, candidate) -> bool:
        if baseline.error_rate == 0:
            return candidate.error_rate > 0.01  # absolute floor if baseline is near-perfect
        relative_increase = (candidate.error_rate - baseline.error_rate) / baseline.error_rate
        return relative_increase > self.MAX_RELATIVE_DEGRADATION

    def rollback(self):
        self.stage_index = 0  # back to 5% / effectively "candidate paused"
        alert_oncall("Canary rollback triggered: candidate error rate regression")

from contextlib import contextmanager
from dataclasses import dataclass
import time

@dataclass
class UsageRecord:
    tenant_id: str
    model: str
    input_tokens: int
    output_tokens: int
    cost_usd: float
    timestamp: float

PRICING = {
    "gpt-tier-large": {"input": 3.00, "output": 15.00},   # per 1M tokens
    "gpt-tier-small": {"input": 0.15, "output": 0.60},
}

class UsageLedger:
    def append(self, record: UsageRecord):
        # durable append-only write; billing queries aggregate from here, not logs
        db.usage_records.insert(record)

ledger = UsageLedger()

@contextmanager
def tracked_model_call(model: str):
    tenant_id = current_request_context.tenant_id  # enforced, not optional
    try:
        yield  # caller performs the actual provider call inside this block
    finally:
        # response is stashed on the context by the provider client wrapper
        usage = current_request_context.last_provider_usage
        if usage is not None:
            price = PRICING[model]
            cost = (usage.input_tokens * price["input"] + usage.output_tokens * price["output"]) / 1_000_000
            ledger.append(UsageRecord(
                tenant_id=tenant_id, model=model,
                input_tokens=usage.input_tokens, output_tokens=usage.output_tokens,
                cost_usd=cost, timestamp=time.time(),
            ))
            # usage is recorded even if the caller's block raised, since this runs in 'finally'

def call_model(model: str, prompt: str):
    with tracked_model_call(model):
        response = provider_client.generate(model=model, prompt=prompt)
        current_request_context.last_provider_usage = response.usage  # actual, not estimated
        return response

def billing_query(tenant_id: str, period_start: float, period_end: float) -> float:
    rows = db.usage_records.query(tenant_id=tenant_id, timestamp_between=(period_start, period_end))
    return sum(r.cost_usd for r in rows)

from enum import Enum

class Decision(Enum):
    ALLOW = "allow"
    BLOCK = "block"
    FLAG_FOR_REVIEW = "flag_for_review"

BLOCK_THRESHOLD = 0.90
REVIEW_THRESHOLD = 0.55

def decide(classifier_result) -> Decision:
    if classifier_result.confidence >= BLOCK_THRESHOLD:
        return Decision.BLOCK
    if classifier_result.confidence >= REVIEW_THRESHOLD:
        return Decision.FLAG_FOR_REVIEW
    return Decision.ALLOW

def handle_request(user_input: str, tenant_id: str):
    input_result = policy_classifier.score(user_input, stage="input")
    input_decision = decide(input_result)
    audit_log.record(stage="input", decision=input_decision, score=input_result.confidence, tenant_id=tenant_id)

    if input_decision == Decision.BLOCK:
        return rejection_response("input_blocked")
    if input_decision == Decision.FLAG_FOR_REVIEW:
        review_queue.enqueue(user_input, tenant_id=tenant_id, stage="input")
        # policy choice for this system: flagged input still proceeds, but the
        # pair will be reviewed; a stricter system could hold here instead

    model_output = llm_client.generate(user_input)

    output_result = policy_classifier.score(model_output, stage="output")
    output_decision = decide(output_result)
    audit_log.record(stage="output", decision=output_decision, score=output_result.confidence, tenant_id=tenant_id)

    if output_decision == Decision.BLOCK:
        return rejection_response("output_blocked")
    if output_decision == Decision.FLAG_FOR_REVIEW:
        review_queue.enqueue(model_output, tenant_id=tenant_id, stage="output")

    return model_output

import time
from enum import Enum

class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"

class CircuitBreaker:
    def __init__(self, failure_threshold=0.5, window_seconds=30,
                 cooldown_seconds=60, probe_count=3):
        self.failure_threshold = failure_threshold
        self.window_seconds = window_seconds
        self.cooldown_seconds = cooldown_seconds
        self.probe_count = probe_count
        self.state = CircuitState.CLOSED
        self.calls = []          # list of (timestamp, success: bool)
        self.opened_at = None
        self.probes_remaining = 0

    def _recent_calls(self):
        cutoff = time.time() - self.window_seconds
        self.calls = [c for c in self.calls if c[0] >= cutoff]
        return self.calls

    def _failure_rate(self) -> float:
        recent = self._recent_calls()
        if not recent:
            return 0.0
        failures = sum(1 for _, ok in recent if not ok)
        return failures / len(recent)

    def allow_request(self) -> bool:
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if time.time() - self.opened_at >= self.cooldown_seconds:
                self.state = CircuitState.HALF_OPEN
                self.probes_remaining = self.probe_count
                return True
            return False  # fail fast, no real call attempted
        if self.state == CircuitState.HALF_OPEN:
            return self.probes_remaining > 0

    def call(self, fn, fallback):
        if not self.allow_request():
            return fallback()
        try:
            result = fn()
            self._record(True)
            return result
        except Exception:
            self._record(False)
            return fallback()

    def _record(self, success: bool):
        self.calls.append((time.time(), success))
        if self.state == CircuitState.HALF_OPEN:
            self.probes_remaining -= 1
            if not success:
                self.state = CircuitState.OPEN
                self.opened_at = time.time()
            elif self.probes_remaining <= 0:
                self.state = CircuitState.CLOSED  # recovery confirmed
        elif self.state == CircuitState.CLOSED and self._failure_rate() > self.failure_threshold:
            self.state = CircuitState.OPEN
            self.opened_at = time.time()

import json
from pathlib import Path

GOLDEN_SET_PATH = Path("eval/golden_sets/route_explainer_v3.json")
BASELINE_PATH = Path("eval/baselines/route_explainer_v3_baseline.json")
REGRESSION_TOLERANCE = 0.03  # allowed aggregate score drop before failing CI

def load_golden_set():
    return json.loads(GOLDEN_SET_PATH.read_text())  # version-controlled, reviewed like code

def load_baseline():
    return json.loads(BASELINE_PATH.read_text())

def run_candidate(candidate_fn, golden_set):
    results = []
    for item in golden_set:
        output = candidate_fn(item["input"])
        score = score_item(item, output)  # pluggable: exact-match, embedding-sim, or LLM-judge
        results.append({"id": item["id"], "score": score, "output": output})
    return results

def score_item(item, output) -> float:
    scorer = item.get("scorer", "llm_judge")
    if scorer == "exact_match":
        return 1.0 if output.strip() == item["reference"].strip() else 0.0
    if scorer == "embedding_sim":
        return embedding_similarity(output, item["reference"])
    return llm_judge_score(output, item["rubric"])  # default

def evaluate(candidate_fn):
    golden_set = load_golden_set()
    baseline = load_baseline()
    results = run_candidate(candidate_fn, golden_set)

    aggregate = sum(r["score"] for r in results) / len(results)
    baseline_aggregate = baseline["aggregate_score"]

    regressions = [
        r for r in results
        if r["score"] < baseline["per_item"].get(r["id"], 1.0) - REGRESSION_TOLERANCE
    ]

    report = {
        "aggregate": aggregate,
        "baseline_aggregate": baseline_aggregate,
        "passed": aggregate >= baseline_aggregate - REGRESSION_TOLERANCE,
        "regressions": regressions,  # specific failing items, not just pass/fail
    }
    Path("eval/last_run_report.json").write_text(json.dumps(report, indent=2))

    if not report["passed"] or regressions:
        raise SystemExit(f"Eval gate failed: aggregate {aggregate:.3f} vs baseline "
                          f"{baseline_aggregate:.3f}; {len(regressions)} item regression(s). "
                          f"See eval/last_run_report.json")
    return report

import time

class TokenBucket:
    def __init__(self, capacity: float, refill_rate_per_sec: float):
        self.capacity = capacity
        self.tokens = capacity
        self.refill_rate = refill_rate_per_sec
        self.last_refill = time.time()

    def _refill(self):
        now = time.time()
        elapsed = now - self.last_refill
        self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_rate)
        self.last_refill = now

    def try_consume(self, cost: float = 1.0) -> bool:
        self._refill()
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

    def seconds_until_available(self, cost: float = 1.0) -> float:
        self._refill()
        deficit = cost - self.tokens
        return max(0.0, deficit / self.refill_rate)


class PerTenantRateLimiter:
    def __init__(self, global_capacity: float, global_refill: float):
        self.tenant_buckets: dict[str, TokenBucket] = {}
        self.tenant_quotas: dict[str, tuple[float, float]] = {}  # (capacity, refill)
        self.global_bucket = TokenBucket(global_capacity, global_refill)  # outer layer

    def set_tenant_quota(self, tenant_id: str, capacity: float, refill_rate_per_sec: float):
        self.tenant_quotas[tenant_id] = (capacity, refill_rate_per_sec)
        self.tenant_buckets[tenant_id] = TokenBucket(capacity, refill_rate_per_sec)

    def allow(self, tenant_id: str) -> tuple[bool, str | None, float | None]:
        bucket = self.tenant_buckets.get(tenant_id)
        if bucket is None:
            raise ValueError(f"No quota configured for tenant {tenant_id}")

        if not bucket.try_consume():
            retry_after = bucket.seconds_until_available()
            return False, "tenant_quota_exceeded", retry_after  # distinct signal: this tenant specifically

        if not self.global_bucket.try_consume():
            bucket.tokens += 1  # refund the tenant token since the request didn't proceed
            retry_after = self.global_bucket.seconds_until_available()
            return False, "global_capacity_exhausted", retry_after  # distinct signal: system-wide

        return True, None, None

import hashlib

def content_hash(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def refresh_index(source_documents, tracking_table, vector_index, embed_fn, chunk_fn):
    seen_source_ids = set()

    for doc in source_documents:
        seen_source_ids.add(doc.source_id)
        new_hash = content_hash(doc.text)
        tracked = tracking_table.get(doc.source_id)

        if tracked is not None and tracked.hash == new_hash:
            continue  # unchanged, skip the expensive re-embed entirely

        # new or changed document: remove old chunks for this source first
        if tracked is not None:
            vector_index.delete_by_source_id(doc.source_id)

        chunks = chunk_fn(doc.text)
        for i, chunk_text in enumerate(chunks):
            chunk_id = f"{doc.source_id}:{i}"  # stable id -> idempotent upsert
            vector = embed_fn(chunk_text)
            vector_index.upsert(chunk_id=chunk_id, vector=vector, metadata={
                "source_id": doc.source_id,
                "text": chunk_text,
                "last_updated": doc.last_modified,
            })

        tracking_table.set(doc.source_id, hash=new_hash, last_indexed=doc.last_modified)

    # handle sources that disappeared entirely (retracted bulletins)
    for source_id in list(tracking_table.all_source_ids()):
        if source_id not in seen_source_ids:
            vector_index.delete_by_source_id(source_id)
            tracking_table.remove(source_id)

