# AFTER (fixed)
def rollback_prompt(template_name: str, target_version: int) -> dict:
    db.prompt_versions.set_active(template_name, target_version)

    # invalidate/refresh the cache on every live instance as part of this operation,
    # not as a separate manual step
    cache_bus.broadcast_invalidate(template_name)

    # verify instances are actually serving the new version before claiming success
    serving_versions = health_check.poll_active_prompt_version(template_name, timeout_sec=10)
    if not all(v == target_version for v in serving_versions.values()):
        return {
            "status": "partial_failure",
            "db_active_version": target_version,
            "serving_versions": serving_versions,  # surfaces exactly which instances are stale
        }

    return {"status": "success", "active_version": target_version, "confirmed_serving": True}
